import csv
import io
import re


_NUMBER = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")


def _is_number(value):
    return bool(_NUMBER.match(value.strip()))


def parse_csv(raw_csv: str):
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"')

    records = []
    try:
        for record in reader:
            if record:
                records.append([str(value) for value in record])
    except csv.Error:
        pass

    if not records:
        return {"columns": ["column_1", "column_2"], "rows": []}

    width = max(2, max(len(record) for record in records))
    has_header = False

    if len(records) > 1:
        first = records[0]
        following = records[1]
        first_has_text = any(value.strip() and not _is_number(value) for value in first)
        following_looks_like_data = any(_is_number(value) for value in following)
        has_header = first_has_text and following_looks_like_data

    if has_header:
        header = records[0]
        width = max(width, len(header))
        columns = header + [f"column_{i + 1}" for i in range(len(header), width)]
        data_records = records[1:]
    else:
        columns = [f"column_{i + 1}" for i in range(width)]
        data_records = records

    rows = []
    for record in data_records:
        normalized = record[:width]
        normalized.extend([""] * (width - len(normalized)))
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
